#include "goal1_native_boundary_history.hpp"
#include "goal1_native_pulse_oracle.hpp"
#include "goal1_native_face_history_boundary.hpp"
#include <iostream>
#include <iomanip>
namespace cs=cubed_sphere;namespace bh=cs::native_boundary_history;namespace h=z4c::hyperboloidal;using J=cs::Jet;
std::array<Real,22>Source(const Real x[3],Real amp,Real width){h::LayerReference<Real>desc(1.,.5,{true,.05,.95});auto p=desc.At(x[0],x[1],x[2]);auto u=cs::native_pulse_oracle::Deviation(x,amp,width);h::AddBackgroundJet(u,p.state);return cs::typed_support::Core(u,p,rwm::ReferenceConnection(p,x));}
std::array<Real,22>Second(const bh::Data&a,const Real x[3],Real step){h::LayerReference<Real>desc(1.,.5,{true,.05,.95});auto p=desc.At(x[0],x[1],x[2]);std::vector<Real>flat;cs::typed_support::Map<Real>(a.first,[&](int,Real v){flat.push_back(v);return v;});auto u=cs::typed_support::Map<Real>(a.initial,[&](int i,Real v){return v+step*flat[i];});return cs::typed_support::Core(u,p,rwm::ReferenceConnection(p,x));}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int status=0;std::cout<<std::setprecision(17);try{int id;Real x[3],amp,width;while(std::cin>>id>>x[0]>>x[1]>>x[2]>>amp>>width){auto a=bh::Build(x,amp,width);h::LayerReference<Real>desc(1.,.5,{true,.05,.95});auto p=desc.At(x[0],x[1],x[2]);std::vector<Real>one,two;cs::typed_support::Map<Real>(a.first,[&](int,Real v){one.push_back(v);return v;});cs::typed_support::Map<Real>(a.second,[&](int,Real v){two.push_back(v);return v;});auto time=cs::typed_support::Map<J>(a.initial,[&](int i,Real v){J q(v);q.d[0]=one[i];q.h[0][0]=two[i];return q;});auto gp=h::Geometry(time.metric);auto pp=cs::typed_support::Constant<J>(p);h::OmegaJet<J>om{};om.omega=pp.omega;for(int i=0;i<3;++i){om.gradient[i]=pp.domega[i];for(int j=0;j<3;++j)om.hessian[i][j]=pp.omega_hessian[i][j];}h::SetStationaryOmegaNormal(time.alpha.value,time.beta.value,time.alpha.d,time.beta.d,om);auto con=h::EvolvedConstraints(time,om);Real C1=std::abs(time.theta.value.d[0]),C2=std::abs(time.theta.value.h[0][0]),H1=std::abs(con.hamiltonian.d[0]),M1=0,alg1=std::abs(gp.determinant.d[0]),alg2=std::abs(gp.determinant.h[0][0]);J atrace;for(int i=0;i<3;++i){J z=time.lambda.value[i]-gp.contracted[i];C1=std::max(C1,std::abs(z.d[0]));C2=std::max(C2,std::abs(z.h[0][0]));M1=std::max(M1,std::abs(con.momentum[i].d[0]));for(int j=0;j<3;++j)atrace+=gp.inverse[i][j]*time.a.k[i][j];}alg1=std::max(alg1,std::abs(atrace.d[0]));alg2=std::max(alg2,std::abs(atrace.h[0][0]));
 Real fderr[2]{},spatialerr[2]{},mixederr[2]{};for(int level=0;level<2;++level){Real eps=level?5e-5:1e-4;auto m2=Second(a,x,-2*eps),m1=Second(a,x,-eps),p1=Second(a,x,eps),p2=Second(a,x,2*eps);for(int n=0;n<22;++n){auto target=cs::operator_oracle::Component(a.second,n);Real value=(m2[n]-8*m1[n]+8*p1[n]-p2[n])/(12*eps);fderr[level]=std::max(fderr[level],std::abs(value-target.value));}
  for(int d=0;d<3;++d){std::array<Real,22>v[4];bh::Data t[4];const int offset[4]={-2,-1,1,2};for(int j=0;j<4;++j){Real xx[3]={x[0],x[1],x[2]};xx[d]+=offset[j]*eps;v[j]=Source(xx,amp,width);t[j]=bh::Build(xx,amp,width);}
   for(int n=0;n<22;++n){auto target=cs::operator_oracle::Component(a.first,n);Real v1=(v[0][n]-8*v[1][n]+8*v[2][n]-v[3][n])/(12*eps);spatialerr[level]=std::max(spatialerr[level],std::abs(v1-target.d[d]));if(bh::Config(n)){Real q[4];for(int j=0;j<4;++j)q[j]=cs::operator_oracle::Component(t[j].second,n).value;auto second=cs::operator_oracle::Component(a.second,n);Real v2=(q[0]-8*q[1]+8*q[2]-q[3])/(12*eps);mixederr[level]=std::max(mixederr[level],std::abs(v2-second.d[d]));}}
  }
 }
 Real basis=0,condition=0;for(Real t:{0.,.0016,.008,.02}){auto u=a.ForBoundaryRows(t,2);Real n[3],r=0;for(auto v:x)r+=v*v;r=std::sqrt(r);for(int i=0;i<3;++i)n[i]=x[i]/r;cs::native_face_boundary::Boundary old,fixed;if(!old.Build(u,n,p.omega)||!fixed.Build(u,n,p.omega,true))throw std::runtime_error("basis invalid");Real ro[10],rf[10];old.Rows(u,p.state,ro);fixed.Rows(u,p.state,rf);h::Z4cRHS<Real>o{},f{};old.Penalty(u,ro,1,o);fixed.Penalty(u,rf,1,f);basis=std::max({basis,std::abs(o.trace-f.trace),std::abs(o.theta-f.theta)});for(int i=0;i<3;++i){basis=std::max(basis,std::abs(o.lambda[i]-f.lambda[i]));for(int j=0;j<3;++j)basis=std::max(basis,std::abs(o.a[i][j]-f.a[i][j]));}}
 std::cout<<"{\"id\":"<<id<<",\"C_time1\":"<<C1<<",\"C_time2\":"<<C2<<",\"H_time1\":"<<H1<<",\"M_time1\":"<<M1<<",\"algebraic_time1\":"<<alg1<<",\"algebraic_time2\":"<<alg2<<",\"basis_native_penalty_difference\":"<<basis<<",\"second_time_FD\":["<<fderr[0]<<","<<fderr[1]<<"],\"first_time_spatial_FD\":["<<spatialerr[0]<<","<<spatialerr[1]<<"],\"second_time_config_gradient_FD\":["<<mixederr[0]<<","<<mixederr[1]<<"]}"<<std::endl;
 }}catch(const std::exception&e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
